# Count connected regions of 0s and 5s
from collections import deque

def count_connected_regions(grid):
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False] * cols for _ in range(rows)]
    regions_5 = []
    regions_0 = []

    def bfs(start_r, start_c, target_val, region_id):
        queue = deque([(start_r, start_c)])
        cells = []
        visited[start_r][start_c] = True
        cells.append((start_r, start_c))

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == target_val:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
                        cells.append((nr, nc))
        return cells

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and not visited[r][c]:
                regions_5.append(bfs(r, c, 5, len(regions_5)))
            elif grid[r][c] == 0 and not visited[r][c]:
                regions_0.append(bfs(r, c, 0, len(regions_0)))

    return regions_0, regions_5

